<script setup lang="ts">
import {Table,TableBody,TableCaption,TableCell,TableHead,TableHeader,TableRow} from '~/components/ui/table'
import {NativeSelect,NativeSelectOption} from '~/components/ui/native-select'
type Entry={id:string;entityType:string;entityId:string;action:string;actor:string;note:string;before:Record<string,unknown>|null;after:Record<string,unknown>|null;createdAt:string}
const admin=useAdmin(),entries=ref<Entry[]>([]),total=ref(0),page=ref(1),size=ref('20'),kind=ref(''),busy=ref(false),error=ref('')
const pages=computed(()=>Math.max(1,Math.ceil(total.value/Number(size.value))))
let request=0
async function load(){if(admin.local)return;const current=++request;busy.value=true;error.value='';try{const data=await $fetch<{entries:Entry[];total:number;page:number}>('/api/admin/audit',{headers:admin.headers.value,query:{page:page.value,pageSize:Number(size.value),...(kind.value?{entityType:kind.value}:{})}});if(current===request){entries.value=data.entries;total.value=data.total;page.value=data.page}}catch(e:any){if(current===request)error.value=e.data?.message||'Could not load change history.'}finally{if(current===request)busy.value=false}}
watch([kind,size],()=>{if(page.value!==1)page.value=1;else load()});watch(page,load);watch(admin.authenticated,value=>{if(value)load()});onMounted(()=>{if(admin.authenticated.value)load()});onBeforeUnmount(()=>request++)
function label(entry:Entry){return entry.after?.tag||entry.before?.tag||entry.after?.name||entry.before?.name||entry.entityId}
</script>
<template>
 <div class="inner-page ops-page audit-page"><AdminLogin v-if="!admin.authenticated.value"/><template v-else><div class="section-heading"><div><h2>Change history</h2><p class="ops-caption">Recorded changes to orders, payments, products and inventory.</p></div><NuxtLink to="/admin/products" class="text-button">Products & inventory</NuxtLink></div><p v-if="admin.local" class="helper">Change history is available in the connected inventory app.</p>
 <div v-else><div class="transaction-filters"><div><label class="field-label" for="audit-kind">Record type</label><NativeSelect id="audit-kind" v-model="kind"><NativeSelectOption value="">All records</NativeSelectOption><NativeSelectOption v-for="type in ['order','stock','product','customer','schedule','expense','settings']" :key="type" :value="type">{{type}}</NativeSelectOption></NativeSelect></div><div><label class="field-label" for="audit-size">Rows per page</label><NativeSelect id="audit-size" v-model="size"><NativeSelectOption v-for="count in [10,20,50,100]" :key="count" :value="String(count)">{{count}}</NativeSelectOption></NativeSelect></div><button class="secondary" :disabled="busy" @click="load">Refresh history</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
 <div class="log-table-card"><Table class="log-table audit-table"><TableCaption class="sr-only">Change history with previous and updated values.</TableCaption><TableHeader><TableRow><TableHead scope="col">When</TableHead><TableHead scope="col">Record</TableHead><TableHead scope="col">Change</TableHead><TableHead scope="col">Details</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="entry in entries" :key="entry.id"><TableCell>{{new Date(entry.createdAt).toLocaleString('en-MY')}}<small class="table-note">{{entry.actor}}</small></TableCell><TableCell>{{label(entry)}}<small class="table-note">{{entry.entityType}}</small></TableCell><TableCell>{{entry.action.replaceAll('_',' ')}}<small class="table-note">{{entry.note}}</small></TableCell><TableCell><details><summary>View changes</summary><strong>Before</strong><pre>{{JSON.stringify(entry.before,null,2)}}</pre><strong>After</strong><pre>{{JSON.stringify(entry.after,null,2)}}</pre></details></TableCell></TableRow><TableRow v-if="!entries.length"><TableCell colspan="4">{{busy?'Loading history…':'No changes recorded yet.'}}</TableCell></TableRow></TableBody></Table></div><div class="transaction-pagination"><p role="status">{{total}} changes</p><nav aria-label="Change history pages"><button class="secondary" :disabled="page<=1||busy" @click="page--">Previous</button><span>Page {{page}} of {{pages}}</span><button class="secondary" :disabled="page>=pages||busy" @click="page++">Next</button></nav></div></div>
 </template></div>
</template>
